CREATE TYPE public.app_role AS ENUM ('user', 'admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TABLE public.diary_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, content text NOT NULL DEFAULT '', entry_date date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.diary_entries TO authenticated; GRANT ALL ON public.diary_entries TO service_role; ALTER TABLE public.diary_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY diary_read ON public.diary_entries FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY diary_write ON public.diary_entries FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.habits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.habits TO authenticated; GRANT ALL ON public.habits TO service_role; ALTER TABLE public.habits ENABLE ROW LEVEL SECURITY;
CREATE POLICY habits_read ON public.habits FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY habits_write ON public.habits FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.habit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), habit_id uuid NOT NULL REFERENCES public.habits(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, log_date date NOT NULL DEFAULT CURRENT_DATE, UNIQUE(habit_id,log_date));
GRANT SELECT,INSERT,DELETE ON public.habit_logs TO authenticated; GRANT ALL ON public.habit_logs TO service_role; ALTER TABLE public.habit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY logs_read ON public.habit_logs FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY logs_insert ON public.habit_logs FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.habits WHERE id=habit_id AND user_id=auth.uid())); CREATE POLICY logs_delete ON public.habit_logs FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), goal_date date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.goals TO authenticated; GRANT ALL ON public.goals TO service_role; ALTER TABLE public.goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY goals_read ON public.goals FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY goals_write ON public.goals FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.goal_progress_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), goal_id uuid NOT NULL REFERENCES public.goals(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, log_date date NOT NULL DEFAULT CURRENT_DATE, progress integer NOT NULL CHECK(progress BETWEEN 0 AND 100), UNIQUE(goal_id,log_date));
GRANT SELECT,INSERT,UPDATE ON public.goal_progress_logs TO authenticated; GRANT ALL ON public.goal_progress_logs TO service_role; ALTER TABLE public.goal_progress_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY goal_progress_read ON public.goal_progress_logs FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY goal_progress_insert ON public.goal_progress_logs FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.goals WHERE id=goal_id AND user_id=auth.uid()));
CREATE POLICY goal_progress_update ON public.goal_progress_logs FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.goals WHERE id=goal_id AND user_id=auth.uid()));
CREATE TABLE public.mood_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, mood integer NOT NULL CHECK(mood BETWEEN 1 AND 5), note text NOT NULL DEFAULT '', log_date date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,log_date));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.mood_logs TO authenticated; GRANT ALL ON public.mood_logs TO service_role; ALTER TABLE public.mood_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY mood_read ON public.mood_logs FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY mood_write ON public.mood_logs FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.shared_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, invite_code uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.shared_tasks TO authenticated; GRANT ALL ON public.shared_tasks TO service_role; ALTER TABLE public.shared_tasks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.shared_task_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES public.shared_tasks(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,user_id));
GRANT SELECT,UPDATE,DELETE ON public.shared_task_members TO authenticated; GRANT ALL ON public.shared_task_members TO service_role; ALTER TABLE public.shared_task_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_task(_task_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.shared_tasks WHERE id=_task_id AND user_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.shared_task_members WHERE task_id=_task_id AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.can_read_task(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_read_task(uuid) TO authenticated;
CREATE POLICY tasks_read ON public.shared_tasks FOR SELECT TO authenticated USING(public.can_read_task(id) OR public.has_role(auth.uid(),'admin')); CREATE POLICY tasks_write ON public.shared_tasks FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY members_read ON public.shared_task_members FOR SELECT TO authenticated USING(public.can_read_task(task_id) OR public.has_role(auth.uid(),'admin')); CREATE POLICY members_update ON public.shared_task_members FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE POLICY members_delete ON public.shared_task_members FOR DELETE TO authenticated USING(user_id=auth.uid());
REVOKE UPDATE ON public.shared_task_members FROM authenticated; GRANT UPDATE(completed) ON public.shared_task_members TO authenticated;
CREATE FUNCTION public.join_shared_task(_code uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT id INTO t FROM public.shared_tasks WHERE invite_code=_code; IF t IS NULL THEN RAISE EXCEPTION 'Шақыру коды табылмады'; END IF; INSERT INTO public.shared_task_members(task_id,user_id) VALUES(t,auth.uid()) ON CONFLICT(task_id,user_id) DO NOTHING; RETURN t; END $$;
REVOKE ALL ON FUNCTION public.join_shared_task(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.join_shared_task(uuid) TO authenticated;
CREATE INDEX diary_owner ON public.diary_entries(user_id); CREATE INDEX habits_owner ON public.habits(user_id); CREATE INDEX habit_logs_owner ON public.habit_logs(user_id); CREATE INDEX habit_logs_habit ON public.habit_logs(habit_id); CREATE INDEX goals_owner ON public.goals(user_id); CREATE INDEX goals_owner_date ON public.goals(user_id,goal_date); CREATE INDEX goal_progress_owner_date ON public.goal_progress_logs(user_id,log_date); CREATE INDEX mood_owner ON public.mood_logs(user_id); CREATE INDEX tasks_owner ON public.shared_tasks(user_id); CREATE INDEX members_owner ON public.shared_task_members(user_id); CREATE INDEX members_task ON public.shared_task_members(task_id);